import{_ as a,a as o,o as t,ae as r}from"./chunks/framework.ckxf1npO.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/getting-started.md","filePath":"zh/guide/getting-started.md"}'),l={name:"zh/guide/getting-started.md"};function d(i,e,n,s,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>欢迎使用 EasyCode Plus！本指南将帮助你快速完成插件的安装与基础配置。</p><h2 id="安装插件" tabindex="-1">安装插件 <a class="header-anchor" href="#安装插件" aria-label="Permalink to &quot;安装插件&quot;">​</a></h2><ol><li>打开 JetBrains 系列 IDE（如 IntelliJ IDEA）。</li><li>进入 <code>Settings</code> &gt; <code>Plugins</code>，搜索 &quot;EasyCode Plus&quot; 并安装。</li><li>重启 IDE 以完成插件安装。</li></ol><h2 id="创建第一个模板" tabindex="-1">创建第一个模板 <a class="header-anchor" href="#创建第一个模板" aria-label="Permalink to &quot;创建第一个模板&quot;">​</a></h2><ol><li>打开任意数据库表，右键选择 &quot;EasyCode Plus&quot; &gt; &quot;生成代码&quot;。</li><li>选择或新建模板组，点击 &quot;编辑模板&quot;。</li><li>编写 Velocity 模板，保存后即可一键生成代码。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><p><strong>生成的模板文件在哪里</strong><br> 在项目的EasyCode目录里面或者Scratches And Consoles的/extensions/EasyCode目录里面,直接编辑模板即可</p></li><li><p><strong>如何自定义作者名？</strong><br> 在插件设置中填写作者信息，或在模板中使用 <code>${author}</code> 变量。</p></li><li><p><strong>支持哪些数据库？</strong><br> 支持所有 JetBrains Database 工具支持的数据库类型。</p></li></ul><h3 id="group-json-做啥用的" tabindex="-1">group.json 做啥用的 <a class="header-anchor" href="#group-json-做啥用的" aria-label="Permalink to &quot;group.json 做啥用的&quot;">​</a></h3><p>group.json是配置关联关系的，模版和globalConfig和typeMapper都是多对多的关系通过配置json的group名来进行区分，一个项目可以有多个生成组</p><h3 id="我不会写模版怎么办" tabindex="-1">我不会写模版怎么办？ <a class="header-anchor" href="#我不会写模版怎么办" aria-label="Permalink to &quot;我不会写模版怎么办？&quot;">​</a></h3><p>模版用的是velocity语法 文档:<a href="https://velocity.apache.org/" target="_blank" rel="noreferrer">https://velocity.apache.org/</a> 碰到模版问题也可联系我来弄弄</p><h3 id="projectpath为空" tabindex="-1">projectPath为空 <a class="header-anchor" href="#projectpath为空" aria-label="Permalink to &quot;projectPath为空&quot;">​</a></h3><p>如果你的项目是一个多module平行的项目，没有一个总的project，可以在mybatisCodehelper.vm中将projectPath set为具体的路径<br> #set($projectPath=&quot;D:/workspace/idea/XXModule&quot;)</p><h3 id="generatecode-old-和generatefromeasycodefolder-new-的区别是啥" tabindex="-1">GenerateCode(old)和GenerateFromEasyCodeFolder(new)的区别是啥 <a class="header-anchor" href="#generatecode-old-和generatefromeasycodefolder-new-的区别是啥" aria-label="Permalink to &quot;GenerateCode(old)和GenerateFromEasyCodeFolder(new)的区别是啥&quot;">​</a></h3><p>GenerateCode(old)老的模版是在设置里面配置的,走的是设置里面的template globalConfig等配置,<br> GenerateFromEasyCodeFolder(new)是直接从easyCode文件夹下的模版生成的.<br> 当你使用GenerateFromEasyCodeFolder(new) 无需在设置里面配置模版，推荐使用GenerateFromEasyCodeFolder(new),<br> 写模版有代码提示，可以实时预览模版，直接在idea编辑器操作模版，还可以加到git中方便与同事共享</p><h3 id="写模版代码提示" tabindex="-1">写模版代码提示 <a class="header-anchor" href="#写模版代码提示" aria-label="Permalink to &quot;写模版代码提示&quot;">​</a></h3><p>模版最上面有个链接 Add dependency for code completion,点击后会自动添加依赖,<br> 之后编辑模版会有代码提示，编辑完模版后可以remove dependency来移除依赖</p><h3 id="为何包名和路径要放在mybatiscodehelper-vm中-为啥不用ui配置路径" tabindex="-1">为何包名和路径要放在mybatisCodeHelper.vm中，为啥不用ui配置路径 <a class="header-anchor" href="#为何包名和路径要放在mybatiscodehelper-vm中-为啥不用ui配置路径" aria-label="Permalink to &quot;为何包名和路径要放在mybatisCodeHelper.vm中，为啥不用ui配置路径&quot;">​</a></h3><p>包名和路径放在mybatisCodeHelper.vm的好处是方便放到git中和同事共享，不用每个人都去配置<br> 未来也可利用这个来进行模版和已存在的文件直接对比，方便找到具体的路径,<br> mybatisCodeHelper.vm的路径和包名未来会加入自动提示，方便填写</p><p>更多高级用法请参考<a href="/EasyCode-Plus/zh/guide/templates.html">模板开发</a>和<a href="/EasyCode-Plus/zh/guide/groovy-script.html">Groovy 脚本</a>章节。</p>',21)])])}const m=a(l,[["render",d]]);export{u as __pageData,m as default};
